contract_clause_fact(contrato_ocs_190_2020, clausula_decima_primeira_obrigações_contratada, obrigacoes, 'atender às solicitações do BNDES relativas à transição contratual entre a CONTRATADA e o seu sucessor na execução do serviço', 'XI').
